/**
 * Translation lookup behind `useTranslation`. English is the base locale:
 * every key lives in en.ts, and each other locale mirrors the full key set
 * (type-checked against `Translations`). Lookups fall back to English, then
 * to the key itself, so a missing translation never renders blank text.
 *
 * Non-English locales are MACHINE-GENERATED by scripts/translate-locales.ts
 * (run `pnpm i18n:translate`) - edit en.ts and re-run the script instead of
 * editing locale files by hand.
 */
import { en, type Translations, type TranslationKey } from "./en";
import { es } from "./es";
import { fr } from "./fr";
import { de } from "./de";
import { pt } from "./pt";
import { zh } from "./zh";
import { ja } from "./ja";
import { ko } from "./ko";
import { hi } from "./hi";
import { ru } from "./ru";
import { pl } from "./pl";
import { nl } from "./nl";
import { it } from "./it";
import { tr } from "./tr";
import { vi } from "./vi";
import { id } from "./id";
import { ar } from "./ar";

export {
  DEFAULT_LANGUAGE,
  languages,
  languageDirection,
  languageLocale,
  resolveLanguage,
  type LanguageOption,
} from "./languages";

const dictionaries: Record<string, Translations> = {
  en,
  es,
  fr,
  de,
  pt,
  zh,
  ja,
  ko,
  hi,
  ru,
  pl,
  nl,
  it,
  tr,
  vi,
  id,
  ar,
};

/** Values a translation's `{{token}}` placeholders can be filled with. */
export type TranslationVars = Record<string, string | number | null | undefined>;

/** Interpolates `{{token}}` placeholders with the given values. */
function interpolate(template: string, vars?: TranslationVars): string {
  if (!vars) return template;
  return template.replace(/\{\{(\w+)\}\}/g, (match, name: string) =>
    name in vars ? String(vars[name] ?? "") : match
  );
}

/** Looks up `key` in `language`, falling back to English, then to the key. */
export function translate(
  language: string,
  key: TranslationKey,
  vars?: TranslationVars
): string {
  const dictionary = dictionaries[language] ?? en;
  const value = dictionary[key] ?? en[key] ?? key;
  return interpolate(value, vars);
}

export { type Translations, type TranslationKey };
